import urllib.request, re
req = urllib.request.Request('https://foxnismone.github.io/hw-collector/?vf2=1')
req.add_header('User-Agent','Mozilla/5.0')
html = urllib.request.urlopen(req, timeout=120).read().decode('utf-8','ignore')
print("HTML en vivo:", len(html))
print("1. drawer abre:", "SI" if 'd.dataset.open="1"' in html else "NO")
print("2. bandera:", "SI" if 'bandera=' in html else "NO")
print("3. catLogoSVG:", "SI" if 'catLogoSVG' in html else "NO")
print("4. barras naranjas:", "SI" if 'Object.keys(det).map' in html else "NO")
print("5. filtro por c.k:", "SI" if 'if(state.cat&&c.k!==state.cat)' in html else "NO")
print("6. CLS con fallback:", "SI" if 'const clsDe=' in html else "NO")
print("7. chips en MAYUSCULA:", "SI" if 'data-clase="CAR CULTURE"' in html else "NO")
print("8. categorias mayus:", "SI" if 'toUpperCase()' in html else "NO")
print("9. CLS 29 claves:", "SI" if "'RLC · RED LINE CLUB'" in html else "NO")
print("10. slugCat:", "SI" if 'const slugCat=' in html else "NO")

